from pathlib import Path
import json
DATA=Path.home()/'.local/share/prediction-chat-bridge'
CID='CONT-1bd188daf0b712e863c2903f'
p=DATA/'continuations'/f'{CID}.json'
if not p.is_file(): raise SystemExit(10)
obj=json.loads(p.read_text(encoding='utf-8'))
event=str(obj.get('last_event_id') or '')
if not event: raise SystemExit(11)
locs=[]
for name in ('outbox','inflight','sent','continuation_abandoned'):
 q=DATA/name/f'{event}.json'
 if q.is_file(): locs.append(name)
print('ASTRA_DELIVERY_LOCATION='+','.join(locs),flush=True)
if locs==['outbox']: raise SystemExit(31)
if locs==['inflight']: raise SystemExit(32)
if locs==['sent']: raise SystemExit(33)
if locs==['continuation_abandoned']: raise SystemExit(34)
if not locs: raise SystemExit(35)
raise SystemExit(36)
